// A real browser request queue. Estimates learn from completed calls; they are never server progress percentages.
import {loadingMessage} from './load-messages.js';
export {LOAD_MESSAGES} from './load-messages.js';
import {ENGINE_SCENES, renderEngineScene, sceneIndexAt} from './engine-scenes.js';
export {ENGINE_SCENES} from './engine-scenes.js';
export function engineScene(index,message=loadingMessage()){return renderEngineScene(index,message);}
export function taskLabel(path){if(path.includes('/twin/fit'))return 'Fitting your KPI history';if(path.includes('/towns'))return 'Building your town';if(path.includes('/trend'))return 'Year analysis';if(path.includes('/timeline'))return 'Operations day';if(path.includes('/days'))return 'Skipped-day analysis';if(path.includes('/vee/'))return 'VEE analysis';if(path.includes('/process/'))return 'Process analysis';if(path.includes('/table'))return 'Data table';return 'Worklists & billing';}
export class AnalysisQueue{
 constructor({fetchImpl,limit=2,now=()=>Date.now(),onChange=()=>{}}){this.fetchImpl=fetchImpl;this.limit=limit;this.now=now;this.onChange=onChange;this.tasks=[];this.durations=new Map();this.finished=0;this.lastError='';}
 snapshot(){const active=this.tasks.filter(t=>t.started!==null),queued=this.tasks.filter(t=>t.started===null);const estimates=this.tasks.map(t=>{const duration=this.durations.get(t.path);return duration==null?null:Math.max(1000,duration-(t.started===null?0:this.now()-t.started));});return {active,queued,finished:this.finished,lastError:this.lastError,overrun:active.some(t=>this.durations.has(t.path)&&this.now()-t.started>this.durations.get(t.path)*1.2),eta:estimates.length&&estimates.every(v=>v!==null)?Math.max(...estimates,estimates.reduce((a,b)=>a+b,0)/this.limit):null};}
 request(input,init,path){return new Promise((resolve,reject)=>{const task={input,init,path,label:taskLabel(path),resolve,reject,started:null};const signal=init?.signal||input?.signal;if(signal?.aborted){reject(signal.reason);return;}task.signal=signal;task.abort=()=>{if(task.started!==null)return;this.tasks=this.tasks.filter(t=>t!==task);reject(signal.reason);signal.removeEventListener('abort',task.abort);this.onChange();};signal?.addEventListener('abort',task.abort,{once:true});if(!this.tasks.length)this.lastError='';this.tasks.push(task);this.onChange();this.pump();});}
 pump(){for(const t of this.tasks){if(this.tasks.filter(t=>t.started!==null).length>=this.limit)break;if(t.started!==null)continue;t.started=this.now();this.onChange();this.run(t);}}
 async run(t){try{const response=await this.fetchImpl(t.input,t.init);const body=await response.arrayBuffer();if(!response.ok)this.lastError=t.label+' failed ('+response.status+').';else{const old=this.durations.get(t.path),elapsed=Math.max(1,this.now()-t.started);this.durations.set(t.path,old==null?elapsed:old*.6+elapsed*.4);this.finished++;}t.resolve(new Response([204,205,304].includes(response.status)?null:body,{status:response.status,statusText:response.statusText,headers:response.headers}));}catch(e){this.lastError=t.label+(t.signal?.aborted?' cancelled.':' could not finish.');t.reject(e);}finally{t.signal?.removeEventListener('abort',t.abort);this.tasks=this.tasks.filter(x=>x!==t);this.onChange();this.pump();}}
}
export function installEngineMonitor(){
 const host=document.createElement('aside');host.className='engine-monitor';host.setAttribute('aria-label','Engine activity');document.body.append(host);
 const native=globalThis.fetch.bind(globalThis),queue=new AnalysisQueue({fetchImpl:native,onChange:render});let expanded=null,lastAnnouncement='',timer=null,sceneIndex=-1,sceneStarted=Date.now();
 globalThis.fetch=(input,init)=>{let url;try{url=new URL(typeof input==='string'||input instanceof URL?input:input.url,location.href);}catch{return native(input,init);}const method=init?.method||input?.method||'GET';return ((method.toUpperCase()==='GET'&&/\/api\/towns\/[^/]+(?:\/snapshot\.json)?$/.test(url.pathname))||method.toUpperCase()==='POST'&&/\/api\/(?:twin\/|m2c\/|process\/|vee\/|sim\/(?:timeline|days)$)/.test(url.pathname))?queue.request(input,init,url.pathname):native(input,init);};
 function render(){const state=queue.snapshot(),n=state.active.length+state.queued.length;
  const title=n?'Your utility is in motion':state.lastError?'Engine needs attention':state.finished?'Analysis complete':'Engine ready';
  if(!host.firstChild){host.innerHTML='<button class="engine-monitor-toggle" aria-expanded="true"><span class="engine-dot"></span><strong></strong><span class="engine-collapse">−</span></button><div class="engine-monitor-body"><div class="engine-scene"></div><div class="engine-counts"></div><ul></ul><div class="engine-estimate"></div></div><span class="engine-announcement" role="status" aria-live="polite"></span>';host.querySelector('button').onclick=()=>{expanded=host.querySelector('button').getAttribute('aria-expanded')!=='true';render();};}
  host.classList.toggle('is-running',n>0);host.classList.toggle('has-error',!!state.lastError&&!n);host.querySelector('strong').textContent=title;const show=expanded??(n>0||!!state.lastError);host.querySelector('button').setAttribute('aria-expanded',String(show));host.querySelector('.engine-collapse').textContent=show?'−':'+';host.querySelector('.engine-monitor-body').hidden=!show;
  const scene=host.querySelector('.engine-scene');if(n&&scene.hidden)sceneStarted=Date.now();const nextScene=sceneIndexAt(Date.now()-sceneStarted);scene.hidden=!n;if(!n)sceneIndex=-1;if(n&&nextScene!==sceneIndex){scene.innerHTML=engineScene(nextScene);scene.setAttribute('aria-label',ENGINE_SCENES[nextScene].name);sceneIndex=nextScene;}
  host.querySelector('.engine-counts').textContent=n?`${state.active.length} running · ${state.queued.length} queued`:state.lastError||'Nothing queued';
  if(n)scene.querySelector('.engine-scene-caption').textContent=loadingMessage();
  const ul=host.querySelector('ul');ul.replaceChildren();for(const t of [...state.active,...state.queued].slice(0,4)){const li=document.createElement('li');li.textContent=t.label+(t.started===null?' · queued':` · ${Math.floor((queue.now()-t.started)/1000)}s elapsed`);ul.append(li);}if(n>4){const li=document.createElement('li');li.textContent=`+ ${n-4} more queued`;ul.append(li);}
  host.querySelector('.engine-estimate').textContent=n?(state.overrun?'Taking longer than recent analyses · still running':state.eta==null?'ETA: learning this analysis time…':`Estimated ${Math.ceil(state.eta/1000)}s remaining · based on recent calls`):'Browser analysis queue';
  const announcement=title+(n?`, ${state.active.length} running and ${state.queued.length} queued`:'.');if(announcement!==lastAnnouncement){host.querySelector('.engine-announcement').textContent=announcement;lastAnnouncement=announcement;}
  if(n&&!timer)timer=setInterval(render,1000);if(!n&&timer){clearInterval(timer);timer=null;}
 }
 render();return queue;
}
